import 'package:flutter_test/flutter_test.dart';import 'package:kinotv/data/models/models.dart';
void main(){test('Movie API raqamlarini to‘g‘ri parse qiladi',(){final m=MovieModel.fromJson({'id':'1','title':'Sinov','description':'Tavsif','posterUrl':'p','bannerUrl':'b','releaseYear':2026,'durationMinutes':90,'rating':'8.7','language':'uz','country':'UZ','videoUrl':'v','genres':[],'categories':[]});expect(m.rating,8.7);expect(m.releaseYear,2026);});test('History ichidagi movie va progress parse qilinadi',(){final m=MovieModel.fromJson({'progress':'25.50','positionSeconds':100,'movie':{'id':'1','title':'Sinov','description':'Tavsif','posterUrl':'p','bannerUrl':'b','releaseYear':2026,'durationMinutes':90,'rating':'8','language':'uz','country':'UZ','videoUrl':'v'}});expect(m.progress,25.5);expect(m.positionSeconds,100);});}
